  "outcome": "deny",
  "rationale": "We must deny the claim because the automated findings and the claimant's account confirm the collision occurred on an unimproved trail. This falls squarely under the off-road use exclusion of the policy. Therefore, the loss is not covered.",
  "citations": [
    {
      "clause_id": "BASIC-4.7",
      "quote": "We do not cover loss that occurs while the covered vehicle is being driven off a maintained public or private road, including on trails, fields, beaches, dunes or other unimproved terrain."
    }
  ]
}
